<script lang="ts">import{defineComponent}from"vue";import{useAdmConsolePage}from"../../app/useAdmConsolePage";export default defineComponent({setup(){return useAdmConsolePage()},name:"CapacityPage",computed:{calls(){return this.serviceRegistryResult?.callHistory||[]},instances(){return this.serviceRegistryResult?.instances||[]},avgLatency(){const v=this.calls.map((x:any)=>Number(x.durationMs||0)).filter((n:number)=>n>=0);return v.length?Math.round(v.reduce((a:number,b:number)=>a+b,0)/v.length):0},failRate(){if(!this.calls.length)return 0;const f=this.calls.filter((x:any)=>!["SUCCESS","OK","COMPLETED"].includes(String(x.callStatus||x.status||'').toUpperCase())).length;return Math.round(f*1000/this.calls.length)/10}}});</script><template><div class="cpf-page"><div class="cpf-page-heading"><div><p class="eyebrow">SLO / CAPACITY</p><h2>용량·SLO 관제</h2><p>최근 호출과 인스턴스 상태를 기반으로 기본 Capacity Signal을 확인합니다.</p></div><button class="ghost" @click="loadServiceRegistry">새로고침</button></div><section class="cpf-kpi-grid"><div class="cpf-stat-card"><span class="label">최근 호출</span><strong class="value">{{calls.length}}</strong></div><div class="cpf-stat-card"><span class="label">평균 지연</span><strong class="value">{{avgLatency}}ms</strong></div><div class="cpf-stat-card"><span class="label">실패율</span><strong class="value">{{failRate}}%</strong></div><div class="cpf-stat-card"><span class="label">인스턴스</span><strong class="value">{{instances.length}}</strong></div></section><section class="cpf-card"><div class="cpf-card-head"><h2>최근 Endpoint 성능</h2></div><div class="table-wrap"><table><thead><tr><th>Service</th><th>Endpoint</th><th>Status</th><th>Latency</th><th>Transaction</th></tr></thead><tbody><tr v-for="r in calls.slice(0,50)" :key="String(r.callId||r.transactionId)"><td>{{r.serviceId}}</td><td>{{r.endpointCode}}</td><td><span class="cpf-status" :class="['SUCCESS','OK','COMPLETED'].includes(String(r.callStatus||'').toUpperCase())?'success':'danger'">{{r.callStatus}}</span></td><td>{{r.durationMs}}ms</td><td>{{r.transactionId}}</td></tr></tbody></table></div></section><p class="cpf-note">장기 추세·Percentile·Capacity Forecast는 Metrics backend 연동 후 Full Verification에서 별도 Evidence로 검증합니다.</p></div></template>
